def parse_duration(s):
    """Seconds in a duration string: "90s", "5m", "1h30m", "2h", "1h5m10s",
    and a bare number means seconds ("45"). Whitespace around it is ignored."""
    s = s.strip()
    if s.endswith("s"):
        return int(s[:-1])
    if s.endswith("m"):
        return int(s[:-1]) * 60
    return int(s)

from dur import parse_duration

def test_minutes():
    assert parse_duration('5m') == 300

def test_mixed():
