import re


def parse_duration(s):
    """Seconds in a duration string: "90s", "5m", "1h30m", "2h", "1h5m10s",
    and a bare number means seconds ("45"). Whitespace around it is ignored."""
    s = s.strip()
    if not s:
        raise ValueError("empty duration string")
    if re.fullmatch(r"\d+", s):
        return int(s)
    total = 0
    matched = 0
    for value, unit in re.findall(r"(\d+)\s*([hms])", s):
        if unit == "h":
            total += int(value) * 3600
        elif unit == "m":
            total += int(value) * 60
        else:
            total += int(value)
        matched += len(value) + 1
    if matched != len(s.replace(" ", "")):
        raise ValueError(f"unparseable duration: {s!r}")
    return total

